public Reliquary(IEventBus modBus, Dist dist, ModContainer container) {
	networkProtocolVersion = container.getModInfo().getVersion().toString();
	NeoForgeMod.enableMilkFluid();
	if (dist == Dist.CLIENT && !ModList.get().isLoaded("configured")) {
		container.registerExtensionPoint(IConfigScreenFactory.class, ConfigurationScreen::new);
	}
	if (dist == Dist.CLIENT) {
		ClientEventHandler.registerHandlers(container);
	}
	modBus.addListener(Reliquary::setup);
	modBus.addListener(Reliquary::loadComplete);
	modBus.addListener(Config::onFileChange);
	modBus.addListener(DataGenerators::gatherData);
	modBus.addListener(ModPayloads::registerPackets);

	ModFluids.registerHandlers(modBus);
	ModItems.registerListeners(modBus);
	ModBlocks.registerListeners(modBus);
	ModEntities.registerListeners(modBus);
	ModEffects.registerListeners(modBus);
	ModSounds.registerListeners(modBus);
	ModParticles.registerListeners(modBus);
	ModDataComponents.register(modBus);

	container.registerConfig(ModConfig.Type.CLIENT, Config.CLIENT_SPEC);
	container.registerConfig(ModConfig.Type.COMMON, Config.COMMON_SPEC);

	IEventBus eventBus = NeoForge.EVENT_BUS;
	CommonEventHandler.registerEventBusListeners(eventBus);
	eventBus.addListener(MobCharmRegistry::handleAddingFragmentDrops);
	eventBus.addListener(AlkahestryRecipeRegistry::onResourceReload);

	ModCompat.initCompats(modBus);
}

public static void registerEventBusListeners(IEventBus eventBus) {
	eventBus.addListener(PassivePedestalBlock::onRightClicked);
	eventBus.addListener(CommonEventHandler::preventMendingAndUnbreaking);
	eventBus.addListener(CommonEventHandler::blameDrullkus);
	eventBus.addListener(CommonEventHandler::beforePlayerHurt);
	eventBus.addListener(CommonEventHandler::beforePlayerDeath);
	eventBus.addListener(CommonEventHandler::onDimensionUnload);
	eventBus.addListener(CommonEventHandler::onPlayerTick);
	eventBus.addListener(PedestalRegistry::serverStopping);
}

public static void registerPlayerDeathHandler(IPlayerDeathHandler handler) {
	playerDeathHandlers.add(handler);
}

public static void beforePlayerDeath(LivingDeathEvent event) {
	Entity entity = event.getEntity();
	if (!(entity instanceof Player player)) {
		return;
	}

	boolean cancel = false;
	for (IPlayerDeathHandler handler : playerDeathHandlers) {
		if (handler.canApply(player, event) && handler.apply(player, event)) {
			cancel = true;
			break;
		}
	}

	if (cancel) {
		event.setCanceled(true);
	}
}

public PhoenixDownItem() {
	super();

	CommonEventHandler.registerPlayerHurtHandler(new IPlayerHurtHandler() {
		@Override
		public boolean canApply(Player player, LivingIncomingDamageEvent event) {
			return event.getSource() == player.damageSources().fall() && player.getHealth() > Math.round(event.getAmount())
					&& player.getFoodData().getFoodLevel() > 0 && InventoryHelper.playerHasItem(player, ModItems.PHOENIX_DOWN.get());
		}

		@Override
		public boolean apply(Player player, LivingIncomingDamageEvent event) {
			float hungerDamage = event.getAmount() * ((float) Config.COMMON.items.phoenixDown.hungerCostPercent.get() / 100F);
			player.causeFoodExhaustion(hungerDamage);
			return true;
		}

		@Override
		public HandlerPriority getPriority() {
			return HandlerPriority.HIGH;
		}
	});

	CommonEventHandler.registerPlayerDeathHandler(new IPlayerDeathHandler() {
		@Override
		public boolean canApply(Player player, LivingDeathEvent event) {
			return InventoryHelper.playerHasItem(player, ModItems.PHOENIX_DOWN.get());
		}

		@Override
		public boolean apply(Player player, LivingDeathEvent event) {
			// item reverts to a normal feather.
			revertPhoenixDownToAngelicFeather(player);

			// gives the player a few hearts, sparing them from death.
			float amountHealed = player.getMaxHealth() * (float) Config.COMMON.items.phoenixDown.healPercentageOfMaxLife.get() / 100F;
			player.setHealth(amountHealed);

			// if the player had any negative status effects [vanilla only for now], remove them:
			if (Boolean.TRUE.equals(Config.COMMON.items.phoenixDown.removeNegativeStatus.get())) {
				EntityHelper.removeNegativeStatusEffects(player);
			}

			// added bonus, has some extra effects when drowning or dying to lava
			if (event.getSource() == player.damageSources().lava()
					&& Boolean.TRUE.equals(Config.COMMON.items.phoenixDown.giveTemporaryFireResistanceIfFireDamageKilledYou.get())) {
				player.addEffect(new MobEffectInstance(MobEffects.FIRE_RESISTANCE, 200, 0));
			}
			if (event.getSource() == player.damageSources().drown()
					&& Boolean.TRUE.equals(Config.COMMON.items.phoenixDown.giveTemporaryWaterBreathingIfDrowningKilledYou.get())) {
				player.setAirSupply(10);
				player.addEffect(new MobEffectInstance(MobEffects.WATER_BREATHING, 200, 0));
			}

			// give the player temporary resistance to other damages.
			if (Boolean.TRUE.equals(Config.COMMON.items.phoenixDown.giveTemporaryDamageResistance.get())) {
				player.addEffect(new MobEffectInstance(MobEffects.DAMAGE_RESISTANCE, 200, 1));
			}

			// give the player temporary regeneration.
			if (Boolean.TRUE.equals(Config.COMMON.items.phoenixDown.giveTemporaryRegeneration.get())) {
				player.addEffect(new MobEffectInstance(MobEffects.REGENERATION, 200, 1));
			}

			// particles, lots of them
			spawnPhoenixResurrectionParticles(player);

			return true;
		}

		@Override
		public HandlerPriority getPriority() {
			return HandlerPriority.LOW;
		}
	});
}

private static void revertPhoenixDownToAngelicFeather(Player player) {
	PlayerInventoryProvider.get().swapFirstFoundItemInPlayerInventoryHandlers(player, ModItems.PHOENIX_DOWN.get(),
			new ItemStack(ModItems.ANGELIC_FEATHER.get()));
}

private static void spawnPhoenixResurrectionParticles(Player player) {
	PacketDistributor.sendToPlayersTrackingEntityAndSelf(player, new SpawnPhoenixDownParticlesPayload(player.position()));
}

public AngelheartVialItem() {
	super(new Properties());

	CommonEventHandler.registerPlayerDeathHandler(new IPlayerDeathHandler() {
		@Override
		public boolean canApply(Player player, LivingDeathEvent event) {
			return InventoryHelper.playerHasItem(player, ModItems.ANGELHEART_VIAL.get());
		}

		@SuppressWarnings({"java:S2440"})
		// instantiating the packet for its type to be used as identifier for the packet
		@Override
		public boolean apply(Player player, LivingDeathEvent event) {
			decreaseAngelHeartByOne(player);

			// player should see a vial "shatter" effect and hear the glass break to
			// let them know they lost a vial.
			PacketDistributor.sendToPlayersTrackingEntityAndSelf(player, new SpawnAngelheartVialParticlesPayload(player.position()));

			// play some glass breaking effects at the player location
			player.level().playSound(null, player.blockPosition(), SoundEvents.GLASS_BREAK, SoundSource.NEUTRAL, 1.0F,
					player.level().random.nextFloat() * 0.1F + 0.9F);

			// gives the player a few hearts, sparing them from death.
			float amountHealed = player.getMaxHealth() * (float) Config.COMMON.items.angelHeartVial.healPercentageOfMaxLife.get() / 100F;
			player.setHealth(amountHealed);

			// if the player had any negative status effects [vanilla only for now], remove them:
			if (Boolean.TRUE.equals(Config.COMMON.items.angelHeartVial.removeNegativeStatus.get())) {
				EntityHelper.removeNegativeStatusEffects(player);
			}

			return true;
		}

		@Override
		public HandlerPriority getPriority() {
			return HandlerPriority.LOW;
		}
	});
}

private static void decreaseAngelHeartByOne(Player player) {
	ItemStack stack = InventoryHelper.getItemFromAllPlayerHandlers(player, ModItems.ANGELHEART_VIAL.get());
	if (!stack.isEmpty()) {
		stack.shrink(1);
	}
}

public int compare(IPrioritizedHandler o1, IPrioritizedHandler o2) {
	int ret = 10 * (o1.getPriority().ordinal() - o2.getPriority().ordinal());
	// 1 os return for same value is required here to prevent treeset from considering two handlers being the same and not inserting them in set
	// noinspection ComparatorMethodParameterNotUsed
	return ret == 0 ? 1 : ret;
}

package reliquary.handler;

public enum HandlerPriority {
	HIGHEST, HIGH, NORMAL, LOW, LOWEST
}

package reliquary.util;

import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.Item;
import net.minecraft.world.item.ItemStack;
import net.neoforged.api.distmarker.Dist;
import net.neoforged.fml.loading.FMLEnvironment;

import java.util.*;
import java.util.function.*;

public class PlayerInventoryProvider {
	public static final String MAIN_INVENTORY = "main";
	public static final String OFFHAND_INVENTORY = "offhand";
	public static final String ARMOR_INVENTORY = "armor";

	private final Map<String, PlayerInventoryHandler> playerInventoryHandlers = new LinkedHashMap<>();
	private final List<String> renderedHandlers = new ArrayList<>();

	private static final PlayerInventoryProvider serverProvider = new PlayerInventoryProvider();
	private static final PlayerInventoryProvider clientProvider = new PlayerInventoryProvider();

	public static PlayerInventoryProvider get() {
		if (FMLEnvironment.dist == Dist.CLIENT) {
			return clientProvider;
		} else {
			return serverProvider;
		}
	}

	private PlayerInventoryProvider() {
		addPlayerInventoryHandler(MAIN_INVENTORY, player -> PlayerInventoryHandler.SINGLE_IDENTIFIER,
				(player, identifier) -> player.getInventory().items.size(), (player, identifier, slot) -> player.getInventory().items.get(slot),
				(player, identifier, slot, stack) -> player.getInventory().setItem(slot, stack), false);
		addPlayerInventoryHandler(OFFHAND_INVENTORY, player -> PlayerInventoryHandler.SINGLE_IDENTIFIER,
				(player, identifier) -> player.getInventory().offhand.size(), (player, identifier, slot) -> player.getInventory().offhand.get(slot),
				(player, identifier, slot, stack) -> player.getInventory().offhand.set(slot, stack), false);
		addPlayerInventoryHandler(ARMOR_INVENTORY, player -> PlayerInventoryHandler.SINGLE_IDENTIFIER,
				(player, identifier) -> player.getInventory().armor.size(), (player, identifier, slot) -> player.getInventory().armor.get(slot),
				(player, identifier, slot, stack) -> player.getInventory().armor.set(slot, stack), true);
	}

	public void addPlayerInventoryHandler(String name, Function<Player, Set<String>> identifiersGetter, PlayerInventoryHandler.SlotCountGetter slotCountGetter,
			PlayerInventoryHandler.SlotStackGetter slotStackGetter, PlayerInventoryHandler.SlotStackSetter slotStackSetter, boolean rendered) {
		Map<String, PlayerInventoryHandler> temp = new LinkedHashMap<>(playerInventoryHandlers);
		playerInventoryHandlers.clear();
		playerInventoryHandlers.put(name, new PlayerInventoryHandler(identifiersGetter, slotCountGetter, slotStackGetter, slotStackSetter));
		playerInventoryHandlers.putAll(temp);

		if (rendered) {
			ArrayList<String> tempRendered = new ArrayList<>(renderedHandlers);
			renderedHandlers.clear();
			renderedHandlers.add(name);
			renderedHandlers.addAll(tempRendered);
		}
	}

	private Map<String, PlayerInventoryHandler> getPlayerInventoryHandlers() {
		return playerInventoryHandlers;
	}

	public void runOnPlayerInventoryHandlers(Player player, Consumer<ItemStack> run) {
		getFromPlayerInventoryHandlers(player, (stack, result) -> {
			run.accept(stack);
			return result;
		}, result -> false, () -> true);
	}

	public void swapFirstFoundItemInPlayerInventoryHandlers(Player player, Item filter, ItemStack replacement) {
		for (var handler : playerInventoryHandlers.values()) {
			Set<String> identifiers = handler.getIdentifiers(player);
			for (String identifier : identifiers) {
				int slots = handler.getSlotCount(player, identifier);
				for (int slot = 0; slot < slots; slot++) {
					ItemStack stack = handler.getStackInSlot(player, identifier, slot);
					if (stack.getItem() == filter) {
						handler.setStackInSlot(player, identifier, slot, replacement);
						return;
					}
				}
			}
		}
	}

	public <T> T getFromPlayerInventoryHandlers(Player player, BiFunction<ItemStack, T, T> get, Predicate<T> shouldExit, Supplier<T> defaultValue) {
		return getFromPlayerInventoryHandlers(player, (stack, handler, handlerName, identifier, slot, result) -> get.apply(stack, result), shouldExit,
				defaultValue);
	}

	public <T> T getFromPlayerInventoryHandlers(Player player, IHandlerSlotValueGetter<T> getter, Predicate<T> shouldExit, Supplier<T> defaultValue) {
		T result = defaultValue.get();
		for (Map.Entry<String, PlayerInventoryHandler> entry : playerInventoryHandlers.entrySet()) {
			String handlerName = entry.getKey();
			PlayerInventoryHandler handler = entry.getValue();
			Set<String> identifiers = handler.getIdentifiers(player);
			for (String identifier : identifiers) {
				int slots = handler.getSlotCount(player, identifier);
				for (int slot = 0; slot < slots; slot++) {
					result = getter.get(handler.getStackInSlot(player, identifier, slot), handler, handlerName, identifier, slot, result);
					if (shouldExit.test(result)) {
						return result;
					}
				}
			}
		}
		return result;
	}

	public ItemStack getStack(Player player, String handlerName, String identifier, int slot) {
		PlayerInventoryHandler handler = playerInventoryHandlers.get(handlerName);
		if (handler != null) {
			return handler.getStackInSlot(player, identifier, slot);
		}
		return ItemStack.EMPTY;
	}

	public void setStack(Player player, String handlerName, String identifier, int slot, ItemStack stack) {
		PlayerInventoryHandler handler = playerInventoryHandlers.get(handlerName);
		if (handler != null) {
			handler.setStackInSlot(player, identifier, slot, stack);
		}
	}

	public interface IHandlerSlotValueGetter<T> {
		T get(ItemStack slotStack, PlayerInventoryHandler handler, String handlerName, String identifier, int slot, T ret);
	}
}

package reliquary.util;

import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;

import java.util.Collections;
import java.util.Set;
import java.util.function.Function;

public class PlayerInventoryHandler {
	public static final Set<String> SINGLE_IDENTIFIER = Collections.singleton("");
	private final Function<Player, Set<String>> identifiersGetter;
	private final SlotCountGetter slotCountGetter;
	private final SlotStackGetter slotStackGetter;
	private final SlotStackSetter slotStackSetter;

	public PlayerInventoryHandler(Function<Player, Set<String>> identifiersGetter, SlotCountGetter slotCountGetter, SlotStackGetter slotStackGetter,
			SlotStackSetter slotStackSetter) {
		this.identifiersGetter = identifiersGetter;
		this.slotCountGetter = slotCountGetter;
		this.slotStackGetter = slotStackGetter;
		this.slotStackSetter = slotStackSetter;
	}

	public int getSlotCount(Player player, String identifier) {
		return slotCountGetter.getSlotCount(player, identifier);
	}

	public ItemStack getStackInSlot(Player player, String identifier, int slot) {
		return slotStackGetter.getStackInSlot(player, identifier, slot);
	}

	public Set<String> getIdentifiers(Player player) {
		return identifiersGetter.apply(player);
	}

	public void setStackInSlot(Player player, String identifier, int slot, ItemStack stack) {
		slotStackSetter.setStackInSlot(player, identifier, slot, stack);
	}

	public interface SlotCountGetter {
		int getSlotCount(Player player, String identifier);
	}

	public interface SlotStackGetter {
		ItemStack getStackInSlot(Player player, String identifier, int slot);
	}

	public interface SlotStackSetter {
		void setStackInSlot(Player player, String identifier, int slot, ItemStack stack);
	}
}

public static boolean playerHasItem(Player player, Item item, boolean checkEnabled) {
	return PlayerInventoryProvider.get().getFromPlayerInventoryHandlers(player, (stack, result) -> {
		if (stack.isEmpty()) {
			return false;
		}
		return stack.getItem() == item
				&& (!(checkEnabled && stack.getItem() instanceof ToggleableItem) || ((ToggleableItem) stack.getItem()).isEnabled(stack));
	}, result -> result, () -> false);
}

public static boolean playerHasItem(Player player, Item item) {
	return playerHasItem(player, item, false);
}

public static ItemStack getItemFromAllPlayerHandlers(Player player, Item item) {
	return PlayerInventoryProvider.get().getFromPlayerInventoryHandlers(player, (stack, result) -> {
		if (stack.isEmpty() || stack.getItem() != item) {
			return ItemStack.EMPTY;
		}

		return stack;
	}, result -> !result.isEmpty(), () -> ItemStack.EMPTY);
}

public static void removeNegativeStatusEffects(LivingEntity player) {
	player.removeEffect(MobEffects.WITHER);
	player.removeEffect(MobEffects.HUNGER);
	player.removeEffect(MobEffects.POISON);
	player.removeEffect(MobEffects.CONFUSION);
	player.removeEffect(MobEffects.DIG_SLOWDOWN);
	player.removeEffect(MobEffects.MOVEMENT_SLOWDOWN);
	player.removeEffect(MobEffects.BLINDNESS);
	player.removeEffect(MobEffects.WEAKNESS);
}

public static void handlePayload(SpawnPhoenixDownParticlesPayload payload) {
	LocalPlayer player = Minecraft.getInstance().player;
	if (player == null) {
		return;
	}

	for (int particles = 0; particles <= 400; particles++) {
		RandomSource random = player.level().random;
		player.level().addParticle(ParticleTypes.FLAME, payload.position.x, payload.position.y, payload.position.z, random.nextGaussian() * 8,
				random.nextGaussian() * 8, random.nextGaussian() * 8);
	}
}

public static void handlePayload(SpawnAngelheartVialParticlesPayload payload) {
	LocalPlayer player = Minecraft.getInstance().player;
	if (player == null) {
		return;
	}

	double x = payload.position.x;
	double y = payload.position.y;
	double z = payload.position.z;
	RandomSource random = player.level().random;
	ItemParticleOption itemParticleData = new ItemParticleOption(ParticleTypes.ITEM, new ItemStack(ModItems.ANGELHEART_VIAL.get()));
	for (int i = 0; i < 8; ++i) {
		player.level().addParticle(itemParticleData, x, y, z, random.nextGaussian() * 0.15D, random.nextDouble() * 0.2D, random.nextGaussian() * 0.15D);
	}

	float red = 1.0F;
	float green = 0.0F;
	float blue = 1.0F;

	for (int i = 0; i < 100; ++i) {
		double distance = random.nextDouble() * 4.0D;
		double angle = random.nextDouble() * Math.PI * 2.0D;
		double xSpeed = Math.cos(angle) * distance;
		double ySpeed = 0.01D + random.nextDouble() * 0.5D;
		double zSpeed = Math.sin(angle) * distance;
		Particle particle = Minecraft.getInstance().particleEngine.createParticle(ParticleTypes.EFFECT, x + xSpeed * 0.1D, y + 0.3D, z + zSpeed * 0.1D,
				xSpeed, ySpeed, zSpeed);
		if (particle != null) {
			float colorMultiplier = 0.75F + random.nextFloat() * 0.25F;
			particle.setColor(red * colorMultiplier, green * colorMultiplier, blue * colorMultiplier);
			particle.setPower((float) distance);
		}
	}
}

public static void registerPackets(final RegisterPayloadHandlersEvent event) {
	final PayloadRegistrar registrar = event.registrar(Reliquary.MOD_ID).versioned(Reliquary.getNetworkProtocolVersion());
	registrar.playToClient(SpawnThrownPotionImpactParticlesPayload.TYPE, SpawnThrownPotionImpactParticlesPayload.STREAM_CODEC,
			(payload1, context1) -> SpawnThrownPotionImpactParticlesPayload.handlePayload(payload1));
	registrar.playToClient(SpawnAngelheartVialParticlesPayload.TYPE, SpawnAngelheartVialParticlesPayload.STREAM_CODEC,
			(payload, context) -> SpawnAngelheartVialParticlesPayload.handlePayload(payload));
	registrar.playToClient(SpawnPhoenixDownParticlesPayload.TYPE, SpawnPhoenixDownParticlesPayload.STREAM_CODEC,
			(payload, context) -> SpawnPhoenixDownParticlesPayload.handlePayload(payload));
	registrar.playToServer(ScrolledItemPayload.TYPE, ScrolledItemPayload.STREAM_CODEC, ScrolledItemPayload::handlePayload);
	registrar.playToClient(SpawnConcussiveExplosionParticlesPayload.TYPE, SpawnConcussiveExplosionParticlesPayload.STREAM_CODEC,
			SpawnConcussiveExplosionParticlesPayload::handlePayload);
	registrar.playToClient(MobCharmDamagePayload.TYPE, MobCharmDamagePayload.STREAM_CODEC,
			(payload, context) -> MobCharmDamagePayload.handlePayload(payload));
	registrar.playToClient(PedestalFishHookPayload.TYPE, PedestalFishHookPayload.STREAM_CODEC,
			(payload, context) -> PedestalFishHookPayload.handlePayload(payload));
	registrar.playToServer(FortuneCoinTogglePressedPayload.TYPE, FortuneCoinTogglePressedPayload.STREAM_CODEC,
			FortuneCoinTogglePressedPayload::handlePayload);
}
